sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
	    // 实时更新数据（每60秒刷新）
    setInterval(function() {
        $scope.server.update().then(function() {
            $scope.$apply();
        });
    }, 60000);
};

sp_widget.css:
.panel {
    margin-bottom: 0;
}
.list-group-item {
    border-left: none;
    border-right: none;
}
.list-group-item:first-child {
    border-top: none;
}

sp_widget.script:
(function() {
    var userId = gs.getUserID(); // 获取当前用户ID
    var pendingRequests = [];

    // 查询sc_req_item表（目录请求项）
    var gr = new GlideRecord('sc_req_item');
    gr.addQuery('opened_by', userId); // 当前用户提交的请求
    gr.addQuery('state', 1); // 状态=1（Pending）
    gr.orderByDesc('sys_created_on'); // 按创建时间倒序
    gr.query();

    // 遍历结果
    while (gr.next()) {
        pendingRequests.push({
            number: gr.number.getDisplayValue(),
            short_description: gr.short_description.getDisplayValue(),
            sys_id: gr.sys_id.toString(),
            catalog_item: gr.cat_item.getDisplayValue(),
            created: gr.sys_created_on.getDisplayValue()
        });
    }

    // 传递数据到客户端
    data.requests = pendingRequests;
})();
